     "time": "08-07 20:30",
     "ts": 1786105809,
     "summary": "北京时间周五晚间，美国劳工统计局披露了一份令市场大呼意外的疲软就业市场报告。 数据显示，7月非农就业人数减少2.3万人，市场预估增加约8万人。 前两个月的就业人数也出现显著下修，其中5月从增加12.9万人下修至增加6.3万人，6月从增加5.7万人下修至增加2万人，两个月合计减少10.3万人。 这一出乎意料的负面数据加剧了人们对美国劳动力市场潜在疲软的担忧。过去一段时间里，美国就业市场一直深陷“低招聘、低裁员”的状态，导致许多求职者面临的机会寥寥无几。 7月失业率报4.1%，市",
     "source": "东方财富资讯",
